__device__ __forceinline__ float block_sum_leader(
    float value, float* warp_sums) {
  for (int offset = 16; offset > 0; offset >>= 1) {
    value += __shfl_down_sync(0xffffffff, value, offset);
  }
  const int lane = static_cast<int>(threadIdx.x) & 31;
  const int warp = static_cast<int>(threadIdx.x) >> 5;
  if (lane == 0) {
    warp_sums[warp] = value;
  }
  __syncthreads();
  if (warp == 0) {
    value = lane < (static_cast<int>(blockDim.x) + 31) / 32
        ? warp_sums[lane]
        : 0.0f;
    for (int offset = 16; offset > 0; offset >>= 1) {
      value += __shfl_down_sync(0xffffffff, value, offset);
    }
  }
  return value;
}

__global__ void panel_qr_wy_kernel(
    const float* input, float* output_v, float* output_t,
    int rows, int width) {
  extern __shared__ float shared[];
  float* matrix = shared;
  const int pitch = width + 1;
  float* t = matrix + rows * pitch;
  float* coefficients = t + width * width;
  float* transformed = coefficients + width;
  float* reduction = transformed + width;
  const int tid = static_cast<int>(threadIdx.x);
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int warp_count = static_cast<int>(blockDim.x) >> 5;
  const int64_t panel_offset =
      static_cast<int64_t>(blockIdx.x) * rows * width;
  const int64_t triangular_offset =
      static_cast<int64_t>(blockIdx.x) * width * width;

  for (int index = tid; index < rows * width; index += blockDim.x) {
    const int row = index / width;
    const int column = index - row * width;
    matrix[row * pitch + column] = input[panel_offset + index];
  }
  for (int index = tid; index < width * width; index += blockDim.x) {
    t[index] = 0.0f;
  }
  __syncthreads();

  for (int column = 0; column < width; ++column) {
    float local_norm = 0.0f;
    for (int row = column + 1 + tid; row < rows; row += blockDim.x) {
      const float value = matrix[row * pitch + column];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, reduction);
    if (tid == 0) {
      const float alpha = matrix[column * pitch + column];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      matrix[column * pitch + column] = beta;
      t[column * width + column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int row = column + 1 + tid; row < rows; row += blockDim.x) {
      matrix[row * pitch + column] *= inverse;
    }
    __syncthreads();

    for (int target = column + 1 + warp; target < width;
         target += warp_count) {
      float partial = 0.0f;
      for (int row = column + lane; row < rows; row += 32) {
        const float reflector = row == column
            ? 1.0f
            : matrix[row * pitch + column];
        partial += reflector * matrix[row * pitch + target];
      }
      for (int offset = 16; offset > 0; offset >>= 1) {
        partial += __shfl_down_sync(0xffffffff, partial, offset);
      }
      const float dot = tau * __shfl_sync(0xffffffff, partial, 0);
      for (int row = column + lane; row < rows; row += 32) {
        const float reflector = row == column
            ? 1.0f
            : matrix[row * pitch + column];
        matrix[row * pitch + target] -= reflector * dot;
      }
    }
    __syncthreads();

